local BookCoverDieMaker = {}
local PRODUCTS = {
    iron_bookcoverdie = { name = "Železni matrica za naslovnice", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni matrica za naslovnice za knjigoveze." },
    bronze_bookcoverdie = { name = "Bronast matrica za naslovnice", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast matrica za naslovnice za knjigoveze." },
    silver_bookcoverdie = { name = "Srebrn matrica za naslovnice", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn matrica za naslovnice za knjigoveze." },
    gilded_bookcoverdie = { name = "Pozlačen matrica za naslovnice", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen matrica za naslovnice za knjigoveze." },
    jewel_set_bookcoverdie = { name = "Draguljast matrica za naslovnice", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast matrica za naslovnice za knjigoveze." },
    royal_sovereign_bookcoverdie = { name = "Kraljevski suveren matrica za naslovnice", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren matrica za naslovnice z biseri za krono." },
}
local BUILDINGS = {
    bookcoverdie_workshop = { name = "Bookcoverdie delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    bookcoverdie_house = { name = "Bookcoverdie hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_bookcoverdie_atelier = { name = "Mojstrski bookcoverdie atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bookcoverdie_palace = { name = "Suverena bookcoverdie palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BookCoverDieMaker.ironStock=18; BookCoverDieMaker.bronzeStock=14; BookCoverDieMaker.woodStock=10; BookCoverDieMaker.leatherStock=8; BookCoverDieMaker.silverStock=8; BookCoverDieMaker.goldStock=6; BookCoverDieMaker.jewelStock=4; BookCoverDieMaker.pearlStock=4
BookCoverDieMaker.productStock = {}; BookCoverDieMaker.buildings = {}; BookCoverDieMaker.maker = nil; BookCoverDieMaker.activeMaking = {}; BookCoverDieMaker.totalProducts = 0; BookCoverDieMaker.dayTimer = 0
function BookCoverDieMaker.init() BookCoverDieMaker.ironStock=18; BookCoverDieMaker.bronzeStock=14; BookCoverDieMaker.woodStock=10; BookCoverDieMaker.leatherStock=8; BookCoverDieMaker.silverStock=8; BookCoverDieMaker.goldStock=6; BookCoverDieMaker.jewelStock=4; BookCoverDieMaker.pearlStock=4; BookCoverDieMaker.productStock={}; BookCoverDieMaker.buildings={}; BookCoverDieMaker.maker=nil; BookCoverDieMaker.activeMaking={}; BookCoverDieMaker.totalProducts=0; BookCoverDieMaker.dayTimer=0; print("[BookCoverDieMaker] Royal Book Cover Die Maker System initialized (6 products, 4 buildings)") end
function BookCoverDieMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookCoverDieMaker.maker={name=n or ("Matrikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Matrikar najet: %s (spretnost: %d)",BookCoverDieMaker.maker.name,s),"success") end; return true end
function BookCoverDieMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookCoverDieMaker.build(id) local ok,e=BookCoverDieMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookCoverDieMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookCoverDieMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookCoverDieMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookCoverDieMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookCoverDieMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookCoverDieMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookCoverDieMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookCoverDieMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookCoverDieMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookCoverDieMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookCoverDieMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookCoverDieMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookCoverDieMaker.buildings==0 then return false,"Potrebna matrikarska delavnica" end; if not BookCoverDieMaker.maker then return false,"Potreben matrikar" end; return true end
function BookCoverDieMaker.make(pt,qty) qty=qty or 1; local ok,e=BookCoverDieMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookCoverDieMaker.ironStock=BookCoverDieMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookCoverDieMaker.bronzeStock=BookCoverDieMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookCoverDieMaker.woodStock=BookCoverDieMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookCoverDieMaker.leatherStock=BookCoverDieMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookCoverDieMaker.silverStock=BookCoverDieMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookCoverDieMaker.goldStock=BookCoverDieMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookCoverDieMaker.jewelStock=BookCoverDieMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookCoverDieMaker.pearlStock=BookCoverDieMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookCoverDieMaker.maker then t=math.max(1,t-math.floor(BookCoverDieMaker.maker.skill/13)) end; table.insert(BookCoverDieMaker.activeMaking,{id="bookcoverdie_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookCoverDieMaker.completeMaking(m) local q=1.0+(BookCoverDieMaker.getQualityBonus()/100); if BookCoverDieMaker.maker then q=q+(BookCoverDieMaker.maker.skill/140) end; q=math.min(2.5,q); BookCoverDieMaker.productStock[m.productType]=(BookCoverDieMaker.productStock[m.productType] or 0)+m.quantity; BookCoverDieMaker.totalProducts=BookCoverDieMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookCoverDieMaker.maker then BookCoverDieMaker.maker.itemsMade=BookCoverDieMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookCoverDieMaker.maker.skill=math.min(100,BookCoverDieMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Matrica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookcoverdie.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookCoverDieMaker.update(dt) if not _G.state then return end; BookCoverDieMaker.dayTimer=BookCoverDieMaker.dayTimer+dt; if BookCoverDieMaker.dayTimer>=30 then BookCoverDieMaker.dayTimer=0; for i=#BookCoverDieMaker.activeMaking,1,-1 do local m=BookCoverDieMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookCoverDieMaker.completeMaking(m); table.remove(BookCoverDieMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookCoverDieMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookCoverDieMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookCoverDieMaker.getStats() return {ironStock=BookCoverDieMaker.ironStock,bronzeStock=BookCoverDieMaker.bronzeStock,woodStock=BookCoverDieMaker.woodStock,leatherStock=BookCoverDieMaker.leatherStock,silverStock=BookCoverDieMaker.silverStock,goldStock=BookCoverDieMaker.goldStock,jewelStock=BookCoverDieMaker.jewelStock,pearlStock=BookCoverDieMaker.pearlStock,productStock=BookCoverDieMaker.productStock,numBuildings=#BookCoverDieMaker.buildings,hasMaker=BookCoverDieMaker.maker~=nil,makerName=BookCoverDieMaker.maker and BookCoverDieMaker.maker.name or "—",makerSkill=BookCoverDieMaker.maker and BookCoverDieMaker.maker.skill or 0,activeMaking=#BookCoverDieMaker.activeMaking,totalProducts=BookCoverDieMaker.totalProducts} end
return BookCoverDieMaker
